// 1) Extract AI response text
const aiText =
  $json?.output?.[0]?.content?.find(c => c.type === "output_text")?.text
  ?? $json?.output?.[0]?.content?.[0]?.text
  ?? $json?.text
  ?? $json?.response
  ?? $json?.content
  ?? "";

if (!String(aiText).trim()) {
  throw new Error("Could not find AI text. Expected $json.output[0].content[*].text");
}

// 2) Clean code fences
let s = String(aiText)
  .trim()
  .replace(/^```(?:json)?\s*/i, "")
  .replace(/```$/i, "")
  .trim();

// 3) Parse JSON (AI Analysis)
let parsed;
try {
  parsed = JSON.parse(s);
} catch (e) {
  throw new Error("AI output is not valid JSON. First 300 chars:\n" + s.slice(0, 300));
}

// -------------------------------------------------------------
// 4) UPSTREAM DATA LOOKUP (Robust Fix)
// -------------------------------------------------------------

// DEFINE YOUR NODE NAMES HERE EXACTLY AS THEY APPEAR IN CANVAS
// We use fallbacks to find the request details
const reqNode = 
  $node["Fetch request from track_requests DB"]?.json ?? 
  $node["Temporary create request"]?.json ?? 
  $node["Create Request in track_requests DB"]?.json ??
  $node["Postgres"]?.json ??
  null;

// Define the PatentsView node name exactly
const patentNode = $node["Fetch Patent data from PatentsView (Unstructured)"]?.json ?? null;

// Validation
const request_id = $json.request_id ?? reqNode?.request_id;
const ticker = $json.ticker ?? reqNode?.ticker;

if (!request_id) throw new Error("Missing request_id. Checked upstream nodes but found nothing.");
if (!ticker) throw new Error("Missing ticker. Checked upstream nodes but found nothing.");

// 5) summary_payload: Store the AI analysis
// The 'parsed' object IS your summary payload (innovation_score, trends, etc.)
const summary_payload = parsed;

// 6) patent_count: Prioritize the API's 'total' count
// PatentsView v1 returns 'total_patent_count' (global) and 'count' (page size).
// If API fails, fall back to AI or array length.
const patent_count = 
  patentNode?.total_patent_count ?? 
  patentNode?.count ?? 
  (Array.isArray(parsed.patents) ? parsed.patents.length : 0);

// 7) created_at
const created_at = new Date().toISOString();

// 8) Output
return [
  {
    json: {
      request_id,
      ticker,
      summary_payload,
      patent_count,
      created_at,
    },
  },
];

