// Get the raw data
const rawData = items[0].json;
const patents = rawData.patents || [];

// Map to a lightweight format for the AI
const slimmed = patents.map(p => {
  return {
    title: p.patent_title,
    date: p.patent_date,
    // Take only first 300 chars of abstract to save tokens
    abstract: (p.patent_abstract || "").substring(0, 300) + "..."
  };
});

// Return the slimmed list AND the total count
return [{
  json: {
    company_name: rawData.company_name || "Target Company", // Ensure this exists from previous node or merge
    total_count: rawData.total_patent_count,
    patents: slimmed
  }
}];
